const $=id=>document.getElementById(id),ctx=$('field').getContext('2d'),KEY='fantasy-battle-lab-v1';let battle=new Battle(),target='enemy-0',busy=false,cutEnabled=true,flash=null,lastFrame=0;
function save(){try{localStorage.setItem(KEY,battle.save());$('save-status').textContent='자동 저장됨 · 이 브라우저';}catch{$('save-status').textContent='저장 공간 사용 불가';}}
function message(t){$('feedback').textContent=t;}
function render(){const p=battle.units[0];$('round').textContent='ROUND '+String(battle.round).padStart(2,'0');$('phase').textContent=busy?'행동 재생 중':battle.status==='playing'?'행동 대기 · 시간 정지':'전투 종료';$('timer').textContent=busy?'진행 중':'결정 중';$('potions').textContent=battle.potions;const enemies=battle.living('enemy');if(!enemies.some(x=>x.id===target))target=enemies[0]?.id;const t=enemies.find(x=>x.id===target);$('target-name').textContent=t?'대상 · '+t.name:'전투 종료';$('intent').textContent=t?(t.windup?'⚠ 다음 적 차례에 공격합니다. ':'접근 거리 '+battle.distance(p,t)+' · ')+(battle.distance(p,t)>1?'공격 시 먼저 접근':'현재 공격 가능'):'새 전투로 다시 테스트할 수 있습니다.';$('units').replaceChildren();for(const u of battle.units){const b=document.createElement('button');b.className='unit '+u.team+(u.id===target?' selected':'');b.disabled=busy||u.hp<=0||u.team==='ally';b.setAttribute('aria-pressed',String(u.id===target));const name=document.createElement('b');name.textContent=u.name+(u.hp<=0?' · 쓰러짐':u.windup?' · 공격 준비':'');const bar=document.createElement('div');bar.className='bar';const fill=document.createElement('i');fill.style.width=u.hp/u.max*100+'%';bar.append(fill);const hp=document.createElement('span');hp.textContent=u.hp+'/'+u.max+(u.id==='taei'?' · MP '+p.mana:'');b.append(name,bar,hp);b.onclick=()=>{target=u.id;render();};$('units').append(b);}for(const b of document.querySelectorAll('#actions button'))b.disabled=busy||battle.status!=='playing';$('input').disabled=busy||battle.status!=='playing';document.querySelector('#command button').disabled=busy||battle.status!=='playing';$('reset').disabled=busy;$('load').disabled=busy;$('result').hidden=battle.status==='playing';$('result').textContent={won:'전투 승리 · 모든 적을 제압했습니다',lost:'전투 불능 · 새 전투에서 다시 시도하세요',fled:'도주 성공 · 전투에서 벗어났습니다'}[battle.status]||'';$('logs').replaceChildren();for(const l of battle.log.slice(-50)){const p=document.createElement('p');p.textContent=l;$('logs').append(p);}$('logs').scrollTop=$('logs').scrollHeight;}
let view={width:960,height:600,dpr:1},camera={x:480,y:280,zoom:0.8};
function resizeField(){const field=$('field');view.width=Math.max(280,window.innerWidth||960);view.height=Math.max(360,window.innerHeight||600);view.dpr=Math.min(2,window.devicePixelRatio||1);field.width=Math.round(view.width*view.dpr);field.height=Math.round(view.height*view.dpr);const mobile=view.width<600;const controlsHeight=$('actions').parentElement?.getBoundingClientRect?.().height|| (mobile?260:220);const top=view.height<600?105:mobile?170:160,bottom=controlsHeight+28;const available=Math.max(140,view.height-top-bottom);camera.zoom=Math.min(1.05,(view.width-60)/1040,available/440);camera.x=view.width/2;camera.y=top+available/2;}
function point(u){return{x:(u.x-3)*100-(u.y-1)*72,y:(u.x-3)*34+(u.y-1)*66};}
function screenPoint(u){const p=point(u);return{x:camera.x+p.x*camera.zoom,y:camera.y+p.y*camera.zoom};}
function diamond(x,y,w,h,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(x,y-h/2);ctx.lineTo(x+w/2,y);ctx.lineTo(x,y+h/2);ctx.lineTo(x-w/2,y);ctx.closePath();ctx.fill();}
function ground(){rect(-2600,-2200,5200,4400,'#40573c');for(let gy=-15;gy<=15;gy++)for(let gx=-20;gx<=20;gx++){const x=gx*72+gy*72,y=gy*36-gx*36;const n=Math.abs((gx*17+gy*31)%11),path=Math.abs(gy-gx)<3;diamond(x,y,144,72,path?(n<4?'#777356':'#716e50'):(n<4?'#405a3b':n<8?'#48613e':'#4b633f'));if(n%3===0){rect(x+12,y,7,3,path?'#8a8463':'#6a7c4b');rect(x-19,y+8,4,4,path?'#5d6047':'#344f33');}}}
function tree(x,y){diamond(x,y+18,96,40,'#1b372b66');rect(x-6,y-28,12,48,'#4b4934');rect(x-8,y-8,6,28,'#383f30');diamond(x,y-48,112,76,'#213c30');diamond(x-14,y-64,92,62,'#2d4b35');diamond(x+17,y-57,80,58,'#345438');diamond(x-5,y-80,66,46,'#3e5e3c');rect(x-23,y-79,14,4,'#587348');}
resizeField();window.addEventListener?.('resize',resizeField);
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
function sprite(u,x,y,frame){ctx.save();ctx.translate(Math.round(x),Math.round(y));ctx.scale(2,2);const enemy=u.team==='enemy';if(!enemy)ctx.scale(-1,1);let bounce=busy?Math.sin(frame*9)*1.2:Math.floor(frame*2)%2;ctx.translate(0,bounce);if(u.hp<=0){ctx.globalAlpha=.2;ctx.rotate(-.8);}const skin=enemy?'#718751':'#d2b6a0',hair=u.kind==='dogyeom'?'#d1c9b8':'#252b2f';if(!enemy){rect(-5,-28,10,8,hair);rect(-4,-21,8,7,skin);rect(-5,-23,10,3,hair);rect(-5,-14,10,12,'#30383b');rect(-8,-14,4,5,'#737b7b');rect(4,-14,4,5,'#737b7b');rect(-8,-9,3,7,skin);rect(5,-9,3,7,skin);rect(-9,-5,4,6,'#7f8585');rect(5,-5,4,6,'#7f8585');if(u.kind==='dogyeom'){rect(-8,-10,3,1,'#343938');rect(5,-8,3,1,'#343938');}rect(-5,-2,4,10,'#343b40');rect(1,-2,4,10,'#343b40');rect(-6,7,5,3,'#57483e');rect(1,7,6,3,'#57483e');rect(-3,-19,2,1,'#c1c8c0');}
else if(u.kind==='slime'){rect(-10,-5,20,12,'#72a5a2');rect(-7,-10,15,10,'#87bfba');rect(-3,-14,8,7,'#a2cebd');rect(-5,-6,2,3,'#477b79');rect(3,-6,2,3,'#477b79');rect(-1,0,4,4,'#d3eac0');rect(-11,6,24,4,'#5b9290');}
else if(u.kind==='ves'){const f=Math.sin(frame*8)>0?0:4;rect(-6,-15,12,14,'#655c72');rect(-6,-25,4,12,'#84718b');rect(2,-25,4,12,'#84718b');rect(-18,-18+f,12,4,'#79657f');rect(-22,-15+f,16,6,'#60536e');rect(6,-18+f,12,4,'#79657f');rect(6,-15+f,16,6,'#60536e');rect(-5,-13,3,2,'#c4a269');rect(2,-13,3,2,'#c4a269');rect(-4,-4,2,7,'#776b72');rect(3,-4,2,7,'#776b72');}
else{rect(-6,-24,12,11,skin);rect(-11,-22,5,4,skin);rect(6,-22,5,4,skin);rect(-5,-13,10,12,'#65543c');rect(-8,-13,3,11,skin);rect(5,-13,3,11,skin);rect(-5,-1,4,10,skin);rect(2,-1,4,10,skin);rect(-5,8,5,3,'#565f3e');rect(2,8,6,3,'#565f3e');rect(-3,-20,2,2,'#cbb366');rect(2,-20,2,2,'#cbb366');rect(8,-20,3,22,'#846d4b');rect(6,-22,7,7,'#a18459');}
ctx.restore();}
function draw(ms){const f=ms/1000;ctx.setTransform(view.dpr,0,0,view.dpr,0,0);ctx.imageSmoothingEnabled=false;rect(0,0,view.width,view.height,'#40573c');ctx.save();ctx.translate(camera.x,camera.y);ctx.scale(camera.zoom,camera.zoom);ground();
for(let y=0;y<3;y++)for(let x=0;x<7;x++){const p=point({x,y});diamond(p.x,p.y,126,65,(x+y)%2?'#bbbc8620':'#b9ba8610');}
const decor=[[-700,-300],[-510,-260],[-300,-340],[-40,-330],[240,-300],[500,-210],[670,-120],[-770,70],[-590,140],[700,210],[-460,340],[370,380],[610,350]];
const drawables=[...decor.map(([x,y])=>({depth:y,tree:true,x,y})),...battle.units.map(u=>({depth:point(u).y,unit:u}))].sort((a,b)=>a.depth-b.depth);
for(const item of drawables){if(item.tree){tree(item.x,item.y);continue;}const u=item.unit,p=point(u),air=u.kind==='ves'?32:0;ctx.fillStyle='#142b2465';ctx.beginPath();ctx.ellipse(p.x,p.y+10,18,8,0,0,Math.PI*2);ctx.fill();if(u.id===target&&u.hp>0){ctx.strokeStyle='#e7cc88';ctx.lineWidth=2/camera.zoom;ctx.beginPath();ctx.ellipse(p.x,p.y+10,25,12,0,0,Math.PI*2);ctx.stroke();}let xx=p.x;if(flash?.actor===u.id&&flash.type==='hit')xx+=u.team==='ally'?12:-12;sprite(u,xx,p.y-air,f);}
ctx.restore();ctx.font='11px sans-serif';ctx.textAlign='center';for(const u of battle.units){if(u.hp<=0)continue;const p=screenPoint(u),air=u.kind==='ves'?32*camera.zoom:0,head=58*camera.zoom;ctx.fillStyle='#10231bdc';ctx.fillRect(p.x-33,p.y-air-head-17,66,16);ctx.fillStyle=u.team==='ally'?'#deead5':'#f0d6b4';ctx.fillText(u.name,p.x,p.y-air-head-5);if(u.windup){ctx.fillStyle='#ffce82';ctx.font='bold 17px sans-serif';ctx.fillText('!',p.x,p.y-air-head-23);ctx.font='11px sans-serif';}if(flash?.target===u.id){ctx.font='bold 19px monospace';ctx.fillStyle='#ffc09d';ctx.fillText(flash.type==='hit'?'-'+flash.damage:flash.type==='miss'?'MISS':'',p.x,p.y-air-head-28);ctx.font='11px sans-serif';}}
requestAnimationFrame(draw);}
async function cut(kind,title){if(!cutEnabled||battle.seen.includes(kind))return;battle.seen.push(kind);const cell={goblin:[0,0],slime:[1,0]}[kind];if(!cell)return;$('cut-art').style.backgroundPosition=(cell[0]*100)+'% '+(cell[1]*100)+'%';$('cut-title').textContent=title;$('cutscene').showModal();save();await new Promise(resolve=>{$('cut-close').onclick=()=>$('cutscene').close();$('cutscene').addEventListener('close',resolve,{once:true});});}
async function act(action){if(busy||battle.status!=='playing')return;let events;try{events=battle.act(action,target);}catch(e){message(e.message);return;}busy=true;save();try{render();for(const event of events){flash=event;message(event.text);await new Promise(r=>setTimeout(r,window.matchMedia('(prefers-reduced-motion:reduce)').matches?90:320));}flash=null;const hit=events.find(e=>e.type==='hit'&&e.actor==='taei');const t=hit&&battle.units.find(u=>u.id===hit.target);if(t&&['goblin','slime'].includes(t.kind)&&(action==='heavy'||battle.units[0].hp<=30)&&battle.units.filter(u=>u.team==='ally').length===1)await cut(t.kind,action==='heavy'?'틈을 파고든 일격':'물러설 곳 없는 순간');}catch(error){message('연출 오류가 발생해 조작을 복구했습니다. '+error.message);}finally{flash=null;busy=false;save();render();}}
document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>act(b.dataset.act));$('command').onsubmit=e=>{e.preventDefault();const raw=$('input').value.trim(),action=battle.parse(raw);if(!action){message('해석하지 못했어요. 공격·강타·방어·회피·접근·후퇴·포션·도주 중 하나를 입력해 주세요.');return;}if(/그리고|다음에|동시에/.test(raw)){message('시제품에서는 한 번에 행동 하나만 입력해 주세요.');return;}act(action);$('input').value='';};$('reset').onclick=()=>{if(busy)return;$('settings-dialog').close();battle=new Battle({kind:$('kind').value,count:Number($('count').value),partner:$('party').value==='duo'});target='enemy-0';save();render();message('새 전투를 시작했습니다. 적을 선택하고 행동하세요.');};$('load').onclick=()=>{try{battle=Battle.restore(localStorage.getItem(KEY));render();message('저장된 전투를 불러왔습니다.');}catch{message('불러올 수 있는 전투 저장이 없습니다.');}};$('cut-toggle').onclick=()=>{cutEnabled=!cutEnabled;$('cut-toggle').textContent='컷신 '+(cutEnabled?'켜짐':'꺼짐');$('cut-toggle').setAttribute('aria-pressed',String(cutEnabled));};$('help').onclick=()=>$('help-dialog').showModal();$('help-close').onclick=()=>$('help-dialog').close();$('field').onclick=e=>{if(busy)return;const r=$('field').getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const found=battle.living('enemy').map(u=>{const p=screenPoint(u);if(u.kind==='ves')p.y-=32*camera.zoom;return{u,p,d:Math.hypot(x-p.x,y-(p.y-20*camera.zoom))};}).filter(a=>a.d<Math.max(24,45*camera.zoom)).sort((a,b)=>a.d-b.d)[0];if(found){target=found.u.id;render();}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||document.querySelector('dialog[open]'))return;const a={1:'attack',2:'heavy',3:'guard',4:'dodge'}[e.key];if(a)act(a);});try{const raw=localStorage.getItem(KEY);if(raw)battle=Battle.restore(raw);}catch{message('저장을 읽지 못해 새 전투로 시작했습니다.');}render();requestAnimationFrame(draw);

$('logs-open').onclick=()=>$('logs-dialog').showModal();
$('logs-close').onclick=()=>$('logs-dialog').close();
$('settings-open').onclick=()=>$('settings-dialog').showModal();
$('settings-close').onclick=()=>$('settings-dialog').close();
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{message('이 브라우저에서는 전체 화면 전환을 지원하지 않습니다. 전장 화면은 그대로 이용할 수 있어요.');}};
